package fetchall

import (
	"context"
	"errors"
	"sync"
)

// Result holds the output of a single operation paired with the index of its
// input in the original inputs slice.
type Result struct {
	Index  int
	Output string
}

// Process runs operation on each input with bounded concurrency, collecting
// successful results ordered by their original index. When at least one
// operation fails, all operations still run and the returned error aggregates
// every individual failure so that each remains reachable via errors.Is /
// errors.As.
func Process(
	ctx context.Context,
	inputs []string,
	concurrency int,
	operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
	if concurrency < 1 {
		return nil, errors.New("fetchall: concurrency must be at least 1")
	}
	if len(inputs) == 0 {
		return nil, nil
	}

	sem := make(chan struct{}, concurrency)
	results := make([]*Result, len(inputs))
	var (
		mu   sync.Mutex
		errs []error
		wg   sync.WaitGroup
	)

	for i, input := range inputs {
		// Acquire semaphore slot before spawning the goroutine.
		sem <- struct{}{}

		i, input := i, input
		wg.Go(func() {
			defer func() { <-sem }()
			out, err := operation(ctx, input)
			mu.Lock()
			if err != nil {
				errs = append(errs, err)
			} else {
				results[i] = &Result{Index: i, Output: out}
			}
			mu.Unlock()
		})
	}

	wg.Wait()

	// Collect only the successful results, which are already in order.
	out := make([]Result, 0, len(inputs))
	for _, r := range results {
		if r != nil {
			out = append(out, *r)
		}
	}

	if len(errs) > 0 {
		return out, errors.Join(errs...)
	}
	return out, nil
}

package fetchall

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestProcess_EmptyInputs(t *testing.T) {
	res, err := Process(context.Background(), nil, 2, nopOp)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
	res, err = Process(context.Background(), []string{}, 2, nopOp)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
}

func TestProcess_InvalidConcurrency(t *testing.T) {
	_, err := Process(context.Background(), []string{"a"}, 0, nopOp)
	if err == nil {
		t.Fatal("expected error for concurrency 0")
	}
	_, err = Process(context.Background(), []string{"a"}, -1, nopOp)
	if err == nil {
		t.Fatal("expected error for concurrency -1")
	}
}

func TestProcess_AllSucceed(t *testing.T) {
	inputs := []string{"a", "b", "c"}
	op := func(_ context.Context, input string) (string, error) {
		return input + "!", nil
	}
	res, err := Process(context.Background(), inputs, 2, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 3 {
		t.Fatalf("expected 3 results, got %d", len(res))
	}
	for i, r := range res {
		if r.Index != i {
			t.Errorf("result %d: expected Index %d, got %d", i, i, r.Index)
		}
		if r.Output != inputs[i]+"!" {
			t.Errorf("result %d: expected Output %q, got %q", i, inputs[i]+"!", r.Output)
		}
	}
}

func TestProcess_ResultsOrderedByIndex(t *testing.T) {
	// Operations complete out of order but results must be in original order.
	inputs := []string{"slow", "fast"}
	var mu sync.Mutex
	started := make(chan struct{}, 2)
	op := func(ctx context.Context, input string) (string, error) {
		mu.Lock()
		started <- struct{}{}
		mu.Unlock()
		if input == "slow" {
			// Wait until "fast" has started, to guarantee out-of-order completion.
			<-ctx.Done()
			return "", ctx.Err()
		}
		return "ok", nil
	}
	// Use a cancel function to unblock slow after fast finishes.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	res, err := Process(ctx, inputs, 2, op)
	if err == nil {
		t.Fatal("expected an error")
	}
	if len(res) != 1 {
		t.Fatalf("expected 1 result, got %d", len(res))
	}
	if res[0].Index != 1 || res[0].Output != "ok" {
		t.Errorf("expected Result{Index: 1, Output: \"ok\"}, got %+v", res[0])
	}
}

func TestProcess_ConcurrencyLimit(t *testing.T) {
	const concurrency = 3
	const total = 10
	var maxSeen int32
	var inflight int32
	var mu sync.Mutex
	started := make(chan struct{}, concurrency)
	done := make(chan struct{}, concurrency)

	op := func(_ context.Context, input string) (string, error) {
		v := atomic.AddInt32(&inflight, 1)
		mu.Lock()
		if int(v) > int(maxSeen) {
			maxSeen = v
		}
		mu.Unlock()

		// Block briefly so we can observe the peak concurrency.
		started <- struct{}{}
		<-done

		atomic.AddInt32(&inflight, -1)
		return input, nil
	}

	go func() {
		for range total {
			started <- struct{}{}
		}
	}()
	go func() {
		for range total {
			done <- struct{}{}
		}
	}()

	res, err := Process(context.Background(), make([]string, total), concurrency, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != total {
		t.Fatalf("expected %d results, got %d", total, len(res))
	}
	if maxSeen > int32(concurrency) {
		t.Errorf("saw %d concurrent operations, limit is %d", maxSeen, concurrency)
	}
}

func TestProcess_MixedFailure(t *testing.T) {
	errFail := errors.New("fail")
	inputs := []string{"ok", "bad", "ok2", "bad2"}
	op := func(_ context.Context, input string) (string, error) {
		if input == "bad" || input == "bad2" {
			return "", errFail
		}
		return input, nil
	}
	res, err := Process(context.Background(), inputs, 2, op)
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	// Each original failure must be reachable via errors.Is.
	var count int
	const target = "fail"
	for current := err; current != nil; {
		if current.Error() == target || errors.Is(current, errFail) {
			count++
			// Unwrap to see if there's a joined error underneath.
		}
		// Walk errors.Join chain.
		unwrapped := errors.Unwrap(current)
		if unwrapped != nil {
			if unwrapped.Error() == target || errors.Is(unwrapped, errFail) {
				count++
			}
		}
		// For errors.Join, iterate through the individual errors.
		type join interface{ Unwrap() []error }
		if joined, ok := current.(join); ok {
			for _, e := range joined.Unwrap() {
				if e.Error() == target || errors.Is(e, errFail) {
					count++
				}
			}
		}
		break
	}
	// Simpler: just check that each individual error is reachable.
	if !errors.Is(err, errFail) {
		t.Error("aggregated error should wrap errFail")
	}
	// Since errFail is the same sentinel for both failures, Is should find it.
	// But we also want to make sure both failures are represented somewhere.
	// errors.Join duplicates the unwrapped errors; counting them tells us.
	var found int
	for _, e := range errors.Unwrap(err).([]error) { //nolint:errorlint
		if errors.Is(e, errFail) {
			found++
		}
	}
	_ = found

	if len(res) != 2 {
		t.Fatalf("expected 2 successful results, got %d", len(res))
	}
	if res[0].Output != "ok" || res[1].Output != "ok2" {
		t.Errorf("unexpected results: %+v", res)
	}
}

func TestProcess_AllFail(t *testing.T) {
	errSentinel := errors.New("boom")
	op := func(_ context.Context, input string) (string, error) {
		return "", errSentinel
	}
	res, err := Process(context.Background(), []string{"a", "b", "c"}, 2, op)
	if err == nil {
		t.Fatal("expected error")
	}
	if res != nil {
		t.Errorf("expected nil results, got %v", res)
	}
	if !errors.Is(err, errSentinel) {
		t.Error("aggregated error should wrap errSentinel")
	}
}

func TestProcess_RespectsContextCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // cancel immediately

	op := func(_ context.Context, input string) (string, error) {
		// Since the parent is cancelled, this should still be called but
		// we return "ok" — the operation doesn't check ctx itself.
		// The spec says the parent context is the parent of every per-operation ctx.
		// The operation is free to check or ignore it.
		// Process itself must still run everything and return.
		return input + "!", nil
	}
	res, err := Process(ctx, []string{"a", "b"}, 2, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 2 {
		t.Fatalf("expected 2 results, got %d", len(res))
	}
}

func TestProcess_ContextCancellationStopsNewOps(t *testing.T) {
	// If the operation itself checks ctx and respects cancellation, we want
	// all operations to run (they'll fail fast) and the aggregated error to
	// include both the ctx error and any other operation errors.
	ctx, cancel := context.WithCancel(context.Background())

	var started, finished sync.WaitGroup
	started.Add(2)
	finished.Add(2)

	op := func(c context.Context, input string) (string, error) {
		started.Done()
		finished.Done()
		// This operation (and all others) must run per the spec.
		// We just ignore context here — the spec says "still runs everything".
		return input, nil
	}

	// Cancel after a brief delay so some operations can start.
	go func() {
		started.Wait()
		cancel()
	}()

	res, err := Process(ctx, []string{"a", "b", "c", "d"}, 2, op)
	// The operations don't check ctx, so they all succeed.
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 4 {
		t.Fatalf("expected 4 results, got %d", len(res))
	}
}

func TestProcess_ErrorsReachable(t *testing.T) {
	var errA = errors.New("errA")
	var errB = errors.New("errB")

	op := func(_ context.Context, input string) (string, error) {
		switch input {
		case "a":
			return "", errA
		case "b":
			return "", errB
		default:
			return input, nil
		}
	}

	res, err := Process(context.Background(), []string{"a", "c", "b", "d"}, 3, op)
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	// Both sentinels must be reachable.
	if !errors.Is(err, errA) {
		t.Error("errA not reachable via errors.Is")
	}
	if !errors.Is(err, errB) {
		t.Error("errB not reachable via errors.Is")
	}
	// Successful results must come back in the right order with correct indices.
	if len(res) != 2 {
		t.Fatalf("expected 2 successful results, got %d", len(res))
	}
	// c (index 1) should come before d (index 3).
	if res[0].Index != 1 || res[0].Output != "c" {
		t.Errorf("first result should be {1, c}, got %+v", res[0])
	}
	if res[1].Index != 3 || res[1].Output != "d" {
		t.Errorf("second result should be {3, d}, got %+v", res[1])
	}
}

func TestProcess_SingleConcurrency(t *testing.T) {
	// Sequential processing with concurrency=1.
	order := make([]int, 0, 3)
	var mu sync.Mutex
	op := func(_ context.Context, input string) (string, error) {
		mu.Lock()
		order = append(order, len(order))
		mu.Unlock()
		return input, nil
	}
	res, err := Process(context.Background(), []string{"x", "y", "z"}, 1, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 3 {
		t.Fatalf("expected 3 results, got %d", len(res))
	}
}

func TestProcess_HighConcurrency(t *testing.T) {
	// concurrency > len(inputs) — all run in parallel.
	n := 100
	inputs := make([]string, n)
	for i := range n {
