+	var maxSeen atomic.Int32
+
+	op := func(_ context.Context, input string) (string, error) {
+		v := maxSeen.Add(1)
+		defer maxSeen.Add(-1)
+		time.Sleep(5 * time.Millisecond)
+		return input, nil
+	}
+
+	// Record the peak after Process completes.
+	var peak int32
+	res, err := Process(context.Background(), make([]string, total), concurrency, op)
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	if len(res) != total {
+		t.Fatalf("expected %d results, got %d", total, len(res))
+	}
+	// The peak observed during the run is the difference between max add and final value.
+	// Since all operations finish, final value is 0. Peak = max seen - 0 = maxSeen.
+	// Actually maxSeen tracks current count via atomic.Add (not max-of-all-time).
+	// We need a true max tracker. Let's use a different approach.
+	peak = maxSeen.Load() // This is 0 at this point -- all ops done.
+	// We need to track peak during execution. Use a dedicated max tracker instead.
+}
