func TestProcess_RespectsContextCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // cancel immediately

	op := func(_ context.Context, input string) (string, error) {
		// Since the parent is cancelled, this should still be called but
		// we return "ok" — the operation doesn't check ctx itself.
		// The spec says the parent context is the parent of every per-operation ctx.
		// The operation is free to check or ignore it.
		// Process itself must still run everything and return.
		return input + "!", nil
	}
	res, err := Process(ctx, []string{"a", "b"}, 2, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 2 {
		t.Fatalf("expected 2 results, got %d", len(res))
	}
}

func TestProcess_ContextCancellationStopsNewOps(t *testing.T) {
	// If the operation itself checks ctx and respects cancellation, we want
	// all operations to run (they'll fail fast) and the aggregated error to
	// include both the ctx error and any other operation errors.
	ctx, cancel := context.WithCancel(context.Background())

	var started, finished sync.WaitGroup
	started.Add(2)
	finished.Add(2)

	op := func(c context.Context, input string) (string, error) {
		started.Done()
		finished.Done()
		// This operation (and all others) must run per the spec.
		// We just ignore context here — the spec says "still runs everything".
		return input, nil
	}

